20	// Helper function to extract user and shortcut ID from shortcut resource name.
21	// Format: users/{user}/shortcuts/{shortcut}.
22	func (s *APIV1Service) extractUserAndShortcutIDFromName(ctx context.Context, name string) (*store.User, string, error) {
23		parts := strings.Split(name, "/")
24		if len(parts) != 4 || parts[0] != "users" || parts[2] != "shortcuts" {
25			return nil, "", errors.Errorf("invalid shortcut name format: %s", name)
26		}
27	
28		user, err := ResolveUserByName(ctx, s.Store, BuildUserName(parts[1]))
29		if err != nil {
30			return nil, "", err
31		}
32		if user == nil {
33			return nil, "", errors.Errorf("user not found: %s", parts[1])
34		}
35	
36		shortcutID := parts[3]
37		if shortcutID == "" {
38			return nil, "", errors.Errorf("empty shortcut ID in name: %s", name)
39		}
40	
41		return user, shortcutID, nil
42	}
43	
44	// Helper function to construct shortcut resource name.
45	func constructShortcutName(username string, shortcutID string) string {
46		return fmt.Sprintf("%s/shortcuts/%s", BuildUserName(username), shortcutID)
47	}
48	
49	func (s *APIV1Service) ListShortcuts(ctx context.Context, request *v1pb.ListShortcutsRequest) (*v1pb.ListShortcutsResponse, error) {
50		user, err := ResolveUserByName(ctx, s.Store, request.Parent)
51		if err != nil {
52			return nil, status.Errorf(codes.InvalidArgument, "invalid user name: %v", err)
53		}
54		if user == nil {
55			return nil, status.Errorf(codes.NotFound, "user not found")
56		}
57		userID := user.ID
58	
59		currentUser, err := s.fetchCurrentUser(ctx)
60		if err != nil {
61			return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
62		}
63		if currentUser == nil || currentUser.ID != userID {
64			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
65		}
66	
67		userSetting, err := s.Store.GetUserSetting(ctx, &store.FindUserSetting{
68			UserID: &userID,
69			Key:    storepb.UserSetting_SHORTCUTS,
70		})
71		if err != nil {
72			return nil, status.Errorf(codes.Internal, "failed to get user setting: %v", err)
73		}
74		if userSetting == nil {
75			return &v1pb.ListShortcutsResponse{
76				Shortcuts: []*v1pb.Shortcut{},
77			}, nil
78		}
79	
80		shortcutsUserSetting := userSetting.GetShortcuts()
81		shortcuts := []*v1pb.Shortcut{}
82		for _, shortcut := range shortcutsUserSetting.GetShortcuts() {
83			shortcuts = append(shortcuts, &v1pb.Shortcut{
84				Name:   constructShortcutName(user.Username, shortcut.GetId()),
85				Title:  shortcut.GetTitle(),
86				Filter: shortcut.GetFilter(),
87			})
88		}
89	
90		return &v1pb.ListShortcutsResponse{
91			Shortcuts: shortcuts,
92		}, nil
93	}
94	
95	func (s *APIV1Service) GetShortcut(ctx context.Context, request *v1pb.GetShortcutRequest) (*v1pb.Shortcut, error) {
96		user, shortcutID, err := s.extractUserAndShortcutIDFromName(ctx, request.Name)
97		if err != nil {
98			return nil, status.Errorf(codes.InvalidArgument, "invalid shortcut name: %v", err)
99		}
100		userID := user.ID
101	
102		currentUser, err := s.fetchCurrentUser(ctx)
103		if err != nil {
104			return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
105		}
106		if currentUser == nil || currentUser.ID != userID {
107			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
108		}
109	
110		userSetting, err := s.Store.GetUserSetting(ctx, &store.FindUserSetting{
111			UserID: &userID,
112			Key:    storepb.UserSetting_SHORTCUTS,
113		})
114		if err != nil {
115			return nil, err
116		}
117		if userSetting == nil {
118			return nil, status.Errorf(codes.NotFound, "shortcut not found")
119		}
120	
121		shortcutsUserSetting := userSetting.GetShortcuts()
122		for _, shortcut := range shortcutsUserSetting.GetShortcuts() {
123			if shortcut.GetId() == shortcutID {
124				return &v1pb.Shortcut{
125					Name:   constructShortcutName(user.Username, shortcut.GetId()),
126					Title:  shortcut.GetTitle(),
127					Filter: shortcut.GetFilter(),
128				}, nil
129			}
130		}
131	
132		return nil, status.Errorf(codes.NotFound, "shortcut not found")
133	}
